import json
import sys
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

books = []


def _send_json(self, status, obj):
    body = json.dumps(obj).encode('utf-8')
    self.send_response(status)
    self.send_header('Content-Type', 'application/json')
    self.send_header('Content-Length', str(len(body)))
    self.end_headers()
    self.wfile.write(body)


class BookHandler(BaseHTTPRequestHandler):
    def _read_json_body(self):
        content_length = int(self.headers.get('Content-Length', 0) or 0)
        raw = self.rfile.read(content_length).decode('utf-8')
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            _send_json(self, 400, {"error": "invalid JSON"})
            return None, None
        if not isinstance(data, dict):
            _send_json(self, 400, {"error": "request body must be a JSON object"})
            return None, None
        return data, None

    def _book_fields(self, data):
        if 'id' in data:
            _send_json(self, 400, {"error": "id must not be supplied"})
            return None, None
        title = data.get('title')
        author = data.get('author')
        isbn = data.get('isbn')
        synopsis = data.get('synopsis', '')
        if not isinstance(title, str) or not title.strip():
            _send_json(self, 400, {"error": "title is required and must be a non-empty string"})
            return None, None
        if not isinstance(author, str) or not author.strip():
            _send_json(self, 400, {"error": "author is required and must be a non-empty string"})
            return None, None
        if not isinstance(isbn, str) or not isbn.strip():
            _send_json(self, 400, {"error": "isbn is required and must be a non-empty string"})
            return None, None
        if not isinstance(synopsis, str):
            _send_json(self, 400, {"error": "synopsis must be a string"})
            return None, None
        return {
            'id': None,
            'title': title.strip(),
            'author': author.strip(),
            'isbn': isbn.strip(),
            'synopsis': synopsis,
        }, None

    def _find_book(self, book_id):
        for book in books:
            if book['id'] == book_id:
                return book
        return None

    def _parse_path(self):
        path = urlparse(self.path).path
        if path == '/books':
            return None, None
        if path.startswith('/books/'):
            rest = path[len('/books/'):]
            if not rest:
                _send_json(self, 404, {"error": "Not found"})
                return None
            try:
                book_id = int(rest)
            except ValueError:
                _send_json(self, 404, {"error": "Not found"})
                return None
            return book_id
        _send_json(self, 404, {"error": "Not found"})
        return None

    def _read_query_params(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)
        allowed = {'id', 'title', 'author', 'isbn', 'synopsis', 'q'}
        for key in params:
            if key not in allowed:
                _send_json(self, 400, {"error": "unknown query parameter"})
                return None
        return params

    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path != '/books':
            _send_json(self, 404, {"error": "Not found"})
            return
        data, err = self._read_json_body()
        if err is not None:
            return
        fields, err = self._book_fields(data)
        if err is not None:
            return
        book_id = len(books) + 1
        book = {
            'id': book_id,
            'title': fields['title'],
            'author': fields['author'],
            'isbn': fields['isbn'],
            'synopsis': fields['synopsis'],
        }
        books.append(book)
        _send_json(self, 201, book)

    def do_GET(self):
        parsed = urlparse(self.path)
        params = self._read_query_params()
        if params is None:
            return
        path = parsed.path

        if path == '/books':
            book_id = params.get('id')
            if book_id is not None:
                q = book_id[0]
                if not q.isdigit():
                    _send_json(self, 404, {"error": "Book not found"})
                    return
                book = self._find_book(int(q))
                if book is None:
                    _send_json(self, 404, {"error": "Book not found"})
                    return
                _send_json(self, 200, book)
                return

            books_sorted = sorted(books, key=lambda b: b['id'])
            result = list(books_sorted)
            q_title = params.get('title', [''])[0]
            q_author = params.get('author', [''])[0]
            q_isbn = params.get('isbn', [''])[0]
            q_synopsis = params.get('synopsis', [''])[0]
            q = params.get('q', [''])[0]

            if q_title:
                result = [b for b in result if b['title'].lower() == q_title.lower()]
            if q_author:
                result = [b for b in result if b['author'].lower() == q_author.lower()]
            if q_isbn:
                result = [b for b in result if b['isbn'].lower() == q_isbn.lower()]
            if q_synopsis:
                result = [b for b in result if q_synopsis.lower() in b['synopsis'].lower()]
            if q:
                like = q.lower()
                result = [b for b in result if like in b['title'].lower()]

            if not result:
                _send_json(self, 200, {"books": [], "count": 0})
            else:
                _send_json(self, 200, {"books": result, "count": len(result)})
            return

        book_id = _parse_path()
        if book_id is None:
            return
        book = self._find_book(book_id)
        if book is None:
            _send_json(self, 404, {"error": "Book not found"})
            return

        if path == '/books/{id}' and parsed.method == 'PUT':
            data, err = self._read_json_body()
            if err is not None:
                return
            fields, err = self._book_fields(data)
            if err is not None:
                return
            book['title'] = fields['title']
            book['author'] = fields['author']
            book['isbn'] = fields['isbn']
            book['synopsis'] = fields['synopsis']
            _send_json(self, 200, book)
            return

        if parsed.method == 'DELETE':
            books.remove(book)
            _send_json(self, 200, {"deleted": True})
            return

        _send_json(self, 501, {"error": "Method not implemented"})


def make_server(port):
    return ThreadingHTTPServer(('127.0.0.1', port), BookHandler)


if __name__ == '__main__':
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8000
    server = make_server(port)
    server.serve_forever()
